// n8n Code node: "Pull new inbound (read only)"
// Reads the WhatsApp bridge store READ ONLY. Never writes to it, never sends.
const { execFileSync } = require('child_process');
const fs = require('fs');

const HOME = process.env.HOME;
const DB = process.env.WA_DIGEST_DB || HOME + '/whatsapp-mcp/whatsapp-bridge/store/messages.db';
const WADB = process.env.WA_DIGEST_WADB || HOME + '/whatsapp-mcp/whatsapp-bridge/store/whatsapp.db';
const WM = process.env.WA_DIGEST_WM || HOME + '/.claude/state/n8n-wa-readonly-last.json';
const LIMIT = 400;
const SQLITE = '/usr/bin/sqlite3';

function q(db, sql) {
  const raw = execFileSync(SQLITE, ['-readonly', '-json', db, sql], {
    encoding: 'utf8', timeout: 25000, maxBuffer: 64 * 1024 * 1024,
  });
  return raw.trim() ? JSON.parse(raw) : [];
}

function hold(reason) {
  // Watermark deliberately untouched so nothing is skipped on the next tick.
  return [{ json: { held: true, reason: reason.slice(0, 300), count: 0, messages: [] } }];
}

// Quiet hours 23:00-08:00 SGT: hold WITHOUT advancing the watermark so overnight
// messages accumulate and land in the first digest after 08:00.
const sgHour = Number(new Intl.DateTimeFormat('en-GB', {
  timeZone: 'Asia/Singapore', hour: '2-digit', hour12: false,
}).format(new Date()));
if (process.env.WA_DIGEST_IGNORE_QUIET !== '1' && (sgHour >= 23 || sgHour < 8)) {
  return [{ json: { held: true, reason: 'quiet hours (SGT ' + sgHour + ')', count: 0, messages: [] } }];
}

let last = null;
try {
  const w = JSON.parse(fs.readFileSync(WM, 'utf8'));
  if (Number.isInteger(w.last_rowid)) last = w.last_rowid;
} catch (e) { last = null; }

let maxRow;
try {
  maxRow = Number(q(DB, 'SELECT COALESCE(MAX(rowid),0) AS m FROM messages;')[0].m);
} catch (e) {
  return hold('bridge store unreadable: ' + String(e.message));
}

function saveWatermark(rowid) {
  const tmp = WM + '.tmp';
  fs.writeFileSync(tmp, JSON.stringify({ last_rowid: rowid }));
  fs.renameSync(tmp, WM);
}

if (last === null) {
  // First run: sit at the newest row. Never backfill the whole history into a digest.
  saveWatermark(maxRow);
  return [{ json: { firstRun: true, watermark: maxRow, count: 0, messages: [] } }];
}

let rows;
try {
  rows = q(DB,
    'SELECT m.rowid AS rowid, m.chat_jid AS chat_jid, m.sender AS sender, ' +
    "m.content AS content, m.timestamp AS ts, COALESCE(m.media_type,'') AS media_type " +
    'FROM messages m ' +
    'WHERE m.rowid > ' + last + ' AND m.is_from_me = 0 ' +
    "AND m.chat_jid NOT LIKE '%@newsletter' AND m.chat_jid <> 'status@broadcast' " +
    'ORDER BY m.rowid LIMIT ' + LIMIT + ';');
} catch (e) {
  return hold('message read failed: ' + String(e.message));
}

if (!rows.length) {
  // Nothing addressed to us, but the store did advance (own sends, newsletters).
  if (maxRow > last) saveWatermark(maxRow);
  return [{ json: { count: 0, messages: [], watermark: Math.max(maxRow, last) } }];
}

// --- identity resolution: @lid -> real phone -> saved contact name ---
const lids = [...new Set(rows.map(r => r.chat_jid).filter(j => j.endsWith('@lid'))
  .map(j => j.slice(0, -4)).filter(s => /^\d+$/.test(s)))];
const phones = [...new Set(rows.map(r => r.chat_jid).filter(j => j.endsWith('@s.whatsapp.net'))
  .map(j => j.slice(0, -15)).filter(s => /^\d+$/.test(s)))];
const groups = [...new Set(rows.map(r => r.chat_jid).filter(j => j.endsWith('@g.us')))];

const NAME = "COALESCE(NULLIF(c.full_name,''), NULLIF(c.push_name,''), NULLIF(c.business_name,''))";
const idn = {};
try {
  if (lids.length) {
    for (const r of q(WADB,
      'SELECT l.lid AS lid, l.pn AS pn, (SELECT ' + NAME + ' FROM whatsmeow_contacts c ' +
      "WHERE c.their_jid = l.pn || '@s.whatsapp.net' OR c.their_jid = l.lid || '@lid' LIMIT 1) AS name " +
      "FROM whatsmeow_lid_map l WHERE l.lid IN ('" + lids.join("','") + "');")) {
      idn[r.lid + '@lid'] = { phone: r.pn, name: r.name || null };
    }
  }
  if (phones.length) {
    for (const r of q(WADB,
      'SELECT c.their_jid AS jid, ' + NAME + ' AS name FROM whatsmeow_contacts c ' +
      "WHERE c.their_jid IN ('" + phones.map(p => p + '@s.whatsapp.net').join("','") + "');")) {
      idn[r.jid] = { phone: r.jid.split('@')[0], name: r.name || null };
    }
  }
} catch (e) { /* names are a nicety: fall back to the raw jid rather than lose the digest */ }

const gname = {};
try {
  if (groups.length) {
    for (const r of q(DB, "SELECT jid, name FROM chats WHERE jid IN ('" +
      groups.filter(g => /^[\d-]+@g\.us$/.test(g)).join("','") + "');")) gname[r.jid] = r.name;
  }
} catch (e) { /* ditto */ }

const KEYWORDS = ['rent', 'rental', 'view', 'viewing', 'available', 'avail', 'price', 'lease',
  'deposit', 'agent', 'unit', 'room', 'condo', 'hdb', 'sale', 'buy', 'sell', '租', '看房', '房'];

const messages = rows.map(r => {
  const isGroup = r.chat_jid.endsWith('@g.us');
  const id = idn[r.chat_jid] || {};
  const body = (r.content || '').trim();
  const low = body.toLowerCase();
  return {
    rowid: r.rowid,
    chat_jid: r.chat_jid,
    isGroup,
    name: isGroup ? (gname[r.chat_jid] || 'group') : (id.name || null),
    phone: id.phone || null,
    ts: r.ts,
    media: r.media_type || null,
    text: body,
    isQuestion: body.includes('?') || body.includes('？'),
    hits: KEYWORDS.filter(k => low.includes(k)),
  };
});

const lastSeen = rows[rows.length - 1].rowid;
saveWatermark(lastSeen);

return [{ json: {
  count: messages.length,
  watermark: lastSeen,
  truncated: messages.length === LIMIT,
  messages,
} }];

// n8n Code node: "Build digest + send to Telegram"
// Plain text only: unescaped Markdown has silently dropped alerts before.
const { execFileSync } = require('child_process');
const fs = require('fs');

const HOME = process.env.HOME;
const ENVF = process.env.WA_DIGEST_ENV || HOME + '/.telegram-bot.env';
const DRY = process.env.WA_DIGEST_DRYRUN === '1';
const MAXLEN = 3500;

const d = $input.first().json;
if (!d.count) return [{ json: { sent: false, reason: d.held ? 'held: ' + d.reason : 'nothing new' } }];

const byChat = new Map();
for (const m of d.messages) {
  if (!byChat.has(m.chat_jid)) byChat.set(m.chat_jid, []);
  byChat.get(m.chat_jid).push(m);
}

function label(m) {
  if (m.isGroup) return (m.name || 'group') + ' [group]';
  const who = m.name || 'unsaved contact';
  return m.phone ? who + ' (+' + m.phone + ')' : who;
}

const dm = [...byChat.entries()].filter(([, v]) => !v[0].isGroup);
const gp = [...byChat.entries()].filter(([, v]) => v[0].isGroup);

const lines = ['WhatsApp inbound digest',
  d.count + ' new message' + (d.count === 1 ? '' : 's') + ' across ' + byChat.size + ' chat' + (byChat.size === 1 ? '' : 's'),
  ''];

function block(entries, heading) {
  if (!entries.length) return;
  lines.push(heading);
  for (const [, msgs] of entries) {
    const flags = [];
    if (msgs.some(m => m.isQuestion)) flags.push('question');
    if (msgs.some(m => m.media)) flags.push('media');
    const hits = [...new Set(msgs.flatMap(m => m.hits))];
    if (hits.length) flags.push(hits.slice(0, 4).join('/'));
    lines.push('- ' + label(msgs[0]) + (flags.length ? '  [' + flags.join(', ') + ']' : ''));
    for (const m of msgs.slice(-3)) {
      const t = m.media && !m.text ? '(' + m.media + ')' : m.text.replace(/\s+/g, ' ').slice(0, 140);
      lines.push('    ' + t);
    }
    if (msgs.length > 3) lines.push('    ...and ' + (msgs.length - 3) + ' more');
  }
  lines.push('');
}

block(dm, 'Direct chats');
block(gp, 'Groups');
if (d.truncated) lines.push('NOTE: batch capped at 400 rows, more will follow next run.');
lines.push('Read only digest. Nothing was sent to anyone.');

let text = lines.join('\n');
if (text.length > MAXLEN) text = text.slice(0, MAXLEN - 40) + '\n...truncated.';

if (DRY) return [{ json: { sent: false, dryRun: true, text } }];

const env = {};
for (const line of fs.readFileSync(ENVF, 'utf8').split('\n')) {
  const m = line.match(/^([A-Z_]+)=(.*)$/);
  if (m) env[m[1]] = m[2].replace(/^["']|["']$/g, '');
}
if (!env.TELEGRAM_BOT_TOKEN || !env.TELEGRAM_WINFRED_CHAT_ID) {
  return [{ json: { sent: false, reason: 'telegram env missing' } }];
}

// Token and body both stay out of argv.
const out = execFileSync('/bin/sh', ['-c',
  'curl -s -m 20 -X POST "https://api.telegram.org/bot$TG_TOKEN/sendMessage" ' +
  '-d chat_id="$TG_CHAT" -d disable_web_page_preview=true --data-urlencode text@-'], {
  env: { ...process.env, TG_TOKEN: env.TELEGRAM_BOT_TOKEN, TG_CHAT: env.TELEGRAM_WINFRED_CHAT_ID },
  input: text, encoding: 'utf8', timeout: 25000,
});

let ok = false;
try { ok = JSON.parse(out).ok === true; } catch (e) { ok = false; }
return [{ json: { sent: ok, chats: byChat.size, count: d.count, response: ok ? 'ok' : out.slice(0, 200) } }];
